content.text:
{
  "watch1": {
    "scenarios": [
      "features/todomvc.feature:Empty list hides the main and footer sections",
      "features/todomvc.feature:New todo input is focused on page load",
      "features/todomvc.feature:Entering a title creates and appends a todo",
      "features/todomvc.feature:New todo title is trimmed before storing",
      "features/todomvc.feature:Whitespace-only new todo is ignored",
      "features/todomvc.feature:Each todo item exposes a destroy button"
    ]
  },
  "watch2": {
    "scenarios": [
      "features/todomvc.feature:Toggling a todo marks it completed",
      "features/todomvc.feature:Toggle-all completes every todo",
      "features/todomvc.feature:Toggle-all reflects all todos completed individually",
      "features/todomvc.feature:Unchecking one todo unchecks toggle-all"
    ]
  },
  "watch3": {
    "scenarios": [
      "features/todomvc.feature:Double-clicking a label enters editing mode",
      "features/todomvc.feature:Editing saves the trimmed title on Enter",
      "features/todomvc.feature:Editing to empty destroys the todo",
      "features/todomvc.feature:Escape during edit discards the change"
    ]
  },
  "watch4": {
    "scenarios": [
      "features/todomvc.feature:Counter shows singular 'item' for one active todo",
      "features/todomvc.feature:Counter shows plural 'items' for multiple active todos",
      "features/todomvc.feature:Counter excludes completed todos from the active count",
      "features/todomvc.feature:Clear completed removes completed todos",
      "features/todomvc.feature:Clear completed is hidden when nothing is completed",
      "features/todomvc.feature:Clear completed unchecks toggle-all"
    ]
  },
  "watch5": {
    "scenarios": [
      "features/todomvc.feature:Todos and their completed state survive a page reload",
      "features/todomvc.feature:Todos persist under the todos-vanilla localStorage key"
    ]
  },
  "watch6": {
    "scenarios": [
      "features/todomvc.feature:Active filter shows only incomplete todos",
      "features/todomvc.feature:Completed filter shows only completed todos",
      "features/todomvc.feature:All filter shows every todo",
      "features/todomvc.feature:Selected filter link reflects the active route",
      "features/todomvc.feature:Active filter persists across reload",
      "features/todomvc.feature:Completing a todo in the active filter hides it"
    ]
  }
}

